import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fml.ModList;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.IForgeRegistry;
import net.minecraftforge.registries.RegistryObject;
import plus.dragons.createenchantmentindustry.EnchantmentIndustry;
import plus.dragons.createenchantmentindustry.content.contraptions.enchanting.enchanter.Enchanting;
import plus.dragons.createenchantmentindustry.entry.CeiFluids;

public class ApotheosisCompat {
    public static final RegistryObject<Potion> KNOWLEDGE = RegistryObject.create((ResourceLocation)new ResourceLocation("apotheosis", "knowledge"), (IForgeRegistry)ForgeRegistries.POTIONS);

    public static void addPotionMixingRecipes() {
        if (!KNOWLEDGE.isPresent()) {
            return;
        }
        PotionMixingRecipes.SUPPORTED_CONTAINERS.stream().filter(container -> PotionBrewing.f_43497_.test(new ItemStack((ItemLike)container))).map(PotionFluidHandler::bottleTypeFromItem).distinct().sorted().forEachOrdered(bottle -> {
            String prefix = switch (bottle) {
                default -> throw new IncompatibleClassChangeError();
                case PotionFluid.BottleType.REGULAR -> "";
                case PotionFluid.BottleType.SPLASH -> "splash_";
                case PotionFluid.BottleType.LINGERING -> "lingering_";
            };
            FluidStack awkward = PotionFluidHandler.getFluidFromPotion((Potion)Potions.f_43602_, (PotionFluid.BottleType)bottle, (int)1000);
            FluidStack knowledge = PotionFluidHandler.getFluidFromPotion((Potion)((Potion)KNOWLEDGE.get()), (PotionFluid.BottleType)bottle, (int)1000);
            MixingRecipe recipe = (MixingRecipe)new ProcessingRecipeBuilder(MixingRecipe::new, EnchantmentIndustry.genRL("compat/apotheosis/potion_mixing/" + prefix + "knowledge")).require((Fluid)CeiFluids.EXPERIENCE.get(), 10).require(FluidIngredient.fromFluidStack((FluidStack)awkward)).output(knowledge).requiresHeat(HeatCondition.HEATED).build();
            PotionMixingRecipes.ALL.add(recipe);
        });
    }

    public static void banTomeFromEnchanter() {
        if (ModList.get().isLoaded("apotheosis")) {
            Enchanting.UNENCHANTABLE_CONDITIONS.add(itemStack -> {
                String id = itemStack.m_41720_().toString();
                return id.startsWith("apotheosis:") && id.contains("tome");
            });
        }
    }
}

